package generator

import (
	"fmt"
)

var initialYAMLLines = []string{
	"---",
	"# Production Infrastructure Configuration",
	"# Automatically generated by CI/CD pipeline",
	"apiVersion: v1",
	"kind: Secret",
	"metadata:",
	"  name: production-application-credentials",
	"  namespace: production",
	"type: Opaque",
	"stringData:",
}

// YAMLGenerator streams YAML configuration.
type YAMLGenerator struct {
	lineCount int
}

// NewYAMLGenerator creates a new YAML generator.
func NewYAMLGenerator() *YAMLGenerator {
	return &YAMLGenerator{}
}

// NextChunk returns the next line of YAML content.
func (g *YAMLGenerator) NextChunk() string {
	idx := g.lineCount
	g.lineCount++

	if idx < len(initialYAMLLines) {
		return initialYAMLLines[idx] + "\n"
	}

	pattern := AllPatterns[RandomInt(len(AllPatterns))]
	key := pattern.EnvKey
	val := pattern.Generate()

	return fmt.Sprintf("  %s: \"%s\"\n", key, val)
}
